import{_ as e,o,c as n,a2 as t}from"./chunks/framework.C0KMm31j.js";const s="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_cover.png",c="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_01_call_architecture.png",i="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_02_configure_load.png",l="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_03_tick_action.png",p="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_04_blackboard_flow.png",r="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_05_navigation_recovery.png",d="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_06_cancel_preempt_result.png",q=JSON.parse('{"title":"Nav2 为什么能边规划边控制？拆解 nav2_behavior_tree 调用全数据流","description":"一台机器人收到导航目标后，并不是简单地依次调用规划器和控制器。","frontmatter":{"title":"Nav2 为什么能边规划边控制？拆解 `nav2_behavior_tree` 调用全数据流","description":"一台机器人收到导航目标后，并不是简单地依次调用规划器和控制器。","date":"2026-07-15","section":"一 · 架构与启动","readingTime":10,"source":"2026-07-15/nav2_behavior_tree_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-15/nav2_behavior_tree_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-behavior-tree-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Nav2 为什么能边规划边控制？拆解 `nav2_behavior_tree` 调用全数据流"}],["meta",{"property":"og:description","content":"一台机器人收到导航目标后，并不是简单地依次调用规划器和控制器。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-behavior-tree-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-15"}],["meta",{"name":"twitter:title","content":"Nav2 为什么能边规划边控制？拆解 `nav2_behavior_tree` 调用全数据流"}],["meta",{"name":"twitter:description","content":"一台机器人收到导航目标后，并不是简单地依次调用规划器和控制器。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-15/nav2_behavior_tree_cover.png"}]],"prev":{"text":"一条导航目标如何指挥整套 Nav2？拆解 `nav2_bt_navigator` 全数据流","link":"/nav2/nav2-bt-navigator-full-dataflow"},"next":{"text":"Nav2 为什么不会“一窝蜂启动”？拆解 `nav2_lifecycle_manager` 全数据流","link":"/nav2/nav2-lifecycle-manager-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-behavior-tree-full-dataflow.md","filePath":"nav2/nav2-behavior-tree-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-behavior-tree-full-dataflow.md"};function b(_,a,u,v,g,k){return o(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="nav2-为什么能边规划边控制-拆解-nav2-behavior-tree-调用全数据流" tabindex="-1">Nav2 为什么能边规划边控制？拆解 <code>nav2_behavior_tree</code> 调用全数据流 <a class="header-anchor" href="#nav2-为什么能边规划边控制-拆解-nav2-behavior-tree-调用全数据流" aria-label="Permalink to &quot;Nav2 为什么能边规划边控制？拆解 `nav2_behavior_tree` 调用全数据流&quot;">​</a></h1><p><img src="'+s+'" alt="封面：Nav2 的决策大脑"></p><p>一台机器人收到导航目标后，并不是简单地依次调用规划器和控制器。</p><p>它要周期性重规划，要在路径变化时更新控制目标，要判断故障发生在规划侧还是控制侧，还要决定清代价地图、旋转、等待和后退的执行顺序。用户取消导航时，已经下发到各服务器的异步任务也必须一起停下来。</p><p>Nav2 把这套决策编排放进了行为树。<code>nav2_behavior_tree</code> 则是行为树与 ROS 2 Action、Service、Topic 之间的连接层。</p><p>这篇文章不只看 XML，而是从一个 <code>/navigate_to_pose</code> 目标出发，完整追踪目标、路径、反馈、恢复次数、取消请求和最终结果怎样流过整个系统。</p><p><img src="'+c+`" alt="图 1：nav2_behavior_tree 调用总览"></p><h2 id="一、先给结论-它不是导航算法-而是导航调度运行时" tabindex="-1">一、先给结论：它不是导航算法，而是导航调度运行时 <a class="header-anchor" href="#一、先给结论-它不是导航算法-而是导航调度运行时" aria-label="Permalink to &quot;一、先给结论：它不是导航算法，而是导航调度运行时&quot;">​</a></h2><p><code>nav2_behavior_tree</code> 不计算全局路径，也不直接输出速度。</p><p>它承担五类职责：</p><h3 id="_1-1-加载行为树节点插件" tabindex="-1">1.1 加载行为树节点插件 <a class="header-anchor" href="#_1-1-加载行为树节点插件" aria-label="Permalink to &quot;1.1 加载行为树节点插件&quot;">​</a></h3><p>把 XML 标签变成可执行的 C++ 节点。</p><h3 id="_1-2-创建和运行行为树" tabindex="-1">1.2 创建和运行行为树 <a class="header-anchor" href="#_1-2-创建和运行行为树" aria-label="Permalink to &quot;1.2 创建和运行行为树&quot;">​</a></h3><p>以固定周期调用 <code>tickRoot()</code>。</p><h3 id="_1-3-通过-blackboard-传递数据" tabindex="-1">1.3 通过 Blackboard 传递数据 <a class="header-anchor" href="#_1-3-通过-blackboard-传递数据" aria-label="Permalink to &quot;1.3 通过 Blackboard 传递数据&quot;">​</a></h3><p>在节点之间传递目标、路径、TF、里程计工具和恢复次数。</p><h3 id="_1-4-转换-ros-2-调用" tabindex="-1">1.4 转换 ROS 2 调用 <a class="header-anchor" href="#_1-4-转换-ros-2-调用" aria-label="Permalink to &quot;1.4 转换 ROS 2 调用&quot;">​</a></h3><p>把树内节点转换成 ROS 2 Action 或 Service 客户端，调用 <code>planner_server</code>、<code>controller_server</code>、<code>behavior_server</code> 和 costmap 服务。</p><h3 id="_1-5-返回任务状态" tabindex="-1">1.5 返回任务状态 <a class="header-anchor" href="#_1-5-返回任务状态" aria-label="Permalink to &quot;1.5 返回任务状态&quot;">​</a></h3><p>把取消、抢占、节点状态日志和最终结果送回外层导航 Action。</p><p>因此，完整调用链不是“行为树直接控制机器人”，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>导航目标</span></span>
<span class="line"><span>  → bt_navigator</span></span>
<span class="line"><span>  → BtActionServer</span></span>
<span class="line"><span>  → BehaviorTreeEngine.tickRoot()</span></span>
<span class="line"><span>  → BT Action／Service 插件</span></span>
<span class="line"><span>  → planner_server／controller_server／behavior_server</span></span>
<span class="line"><span>  → 路径或运动结果</span></span>
<span class="line"><span>  → Blackboard／树节点状态</span></span>
<span class="line"><span>  → 导航 feedback／result</span></span></code></pre></div><h2 id="二、配置阶段-先造工厂-再造树" tabindex="-1">二、配置阶段：先造工厂，再造树 <a class="header-anchor" href="#二、配置阶段-先造工厂-再造树" aria-label="Permalink to &quot;二、配置阶段：先造工厂，再造树&quot;">​</a></h2><p><code>BtActionServer&lt;ActionT&gt;</code> 是外层导航 Action 与行为树运行时之间的总入口。<code>NavigateToPoseNavigator</code> 和 <code>NavigateThroughPosesNavigator</code> 都通过这个模板类获得自己的 Action Server。</p><p>在 <code>on_configure()</code> 阶段，它不会立刻执行 XML，而是先完成运行环境装配。</p><p><img src="`+i+`" alt="图 2：配置、插件注册和 XML 装载"></p><h3 id="_2-1-创建专用-client-node" tabindex="-1">2.1 创建专用 client node <a class="header-anchor" href="#_2-1-创建专用-client-node" aria-label="Permalink to &quot;2.1 创建专用 client node&quot;">​</a></h3><p><code>BtActionServer</code> 创建一个普通 <code>rclcpp::Node</code>，名字带 <code>_rclcpp_node</code> 后缀，并把父 LifecycleNode 的参数复制过来。</p><p>这个节点不是新的导航服务器，它是行为树内部所有 ROS 客户端的共同宿主。树内的 Action、Service、订阅器和状态日志发布器都从 Blackboard 取出这个节点。</p><h3 id="_2-2-动态注册插件" tabindex="-1">2.2 动态注册插件 <a class="header-anchor" href="#_2-2-动态注册插件" aria-label="Permalink to &quot;2.2 动态注册插件&quot;">​</a></h3><p><code>BehaviorTreeEngine</code> 构造时遍历 <code>plugin_lib_names</code>：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">factory_.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">registerFromPlugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(loader.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getOSName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(plugin));</span></span></code></pre></div><p>每个插件动态库通过 <code>BT_REGISTER_NODES</code> 注册自己的 XML 标签。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComputePathToPose → ComputePathToPoseAction</span></span>
<span class="line"><span>FollowPath        → FollowPathAction</span></span>
<span class="line"><span>ClearEntireCostmap → ClearEntireCostmapService</span></span>
<span class="line"><span>RecoveryNode      → RecoveryNode</span></span>
<span class="line"><span>RoundRobin        → RoundRobinNode</span></span></code></pre></div><p>这解释了一个常见误区：<code>nav2_tree_nodes.xml</code> 主要描述 Groot 可识别的节点模型和端口，真正决定运行时能否实例化节点的是 <code>plugin_lib_names</code> 与动态库注册代码。</p><h3 id="_2-3-建立-blackboard-基础设施" tabindex="-1">2.3 建立 Blackboard 基础设施 <a class="header-anchor" href="#_2-3-建立-blackboard-基础设施" aria-label="Permalink to &quot;2.3 建立 Blackboard 基础设施&quot;">​</a></h3><p>根 Blackboard 首先写入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node                     行为树 ROS 客户端节点</span></span>
<span class="line"><span>server_timeout           单次请求确认／响应超时</span></span>
<span class="line"><span>bt_loop_duration         行为树循环周期</span></span>
<span class="line"><span>wait_for_service_timeout 等待服务上线的超时</span></span>
<span class="line"><span>tf_buffer                TF 查询入口</span></span>
<span class="line"><span>odom_smoother             平滑速度入口</span></span>
<span class="line"><span>number_recoveries         恢复动作计数</span></span></code></pre></div><p>进入 <code>on_activate()</code> 后，服务器读取默认 XML；如果导航目标指定了另一个 <code>behavior_tree</code> 文件，则接收目标时重新加载。<code>createTreeFromText()</code> 根据 XML 标签实例化已经注册的插件，并为 subtree Blackboard 补写共同的 node 和 timeout 数据。</p><p>最后才激活 <code>/navigate_to_pose</code> 或 <code>/navigate_through_poses</code> Action Server。</p><h2 id="三、一个导航目标如何进入行为树" tabindex="-1">三、一个导航目标如何进入行为树 <a class="header-anchor" href="#三、一个导航目标如何进入行为树" aria-label="Permalink to &quot;三、一个导航目标如何进入行为树&quot;">​</a></h2><p>当 <code>/navigate_to_pose</code> 收到 Goal，外层先经过 Navigator 互斥检查。同一时间只允许一个 Navigator 处于导航状态，避免单目标导航和多目标导航同时控制系统。</p><p>目标通过检查后，<code>NavigateToPoseNavigator::goalReceived()</code> 做两件事。</p><h3 id="_3-1-加载行为树文件" tabindex="-1">3.1 加载行为树文件 <a class="header-anchor" href="#_3-1-加载行为树文件" aria-label="Permalink to &quot;3.1 加载行为树文件&quot;">​</a></h3><p>加载 Goal 指定的行为树文件；字段为空时继续使用默认树。</p><h3 id="_3-2-写入任务数据" tabindex="-1">3.2 写入任务数据 <a class="header-anchor" href="#_3-2-写入任务数据" aria-label="Permalink to &quot;3.2 写入任务数据&quot;">​</a></h3><p>把 <code>goal-&gt;pose</code> 写入 Blackboard 的 <code>goal</code> 键，并把 <code>number_recoveries</code> 清零。</p><h3 id="_3-3-运行行为树循环" tabindex="-1">3.3 运行行为树循环 <a class="header-anchor" href="#_3-3-运行行为树循环" aria-label="Permalink to &quot;3.3 运行行为树循环&quot;">​</a></h3><p>随后 <code>BtActionServer::executeCallback()</code> 调用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bt_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tree_, on_loop, is_canceling, bt_loop_duration_);</span></span></code></pre></div><p><code>BehaviorTreeEngine::run()</code> 的循环很短，但它是整套调度的时钟：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查取消</span></span>
<span class="line"><span>  → tree.tickRoot()</span></span>
<span class="line"><span>  → 发布 feedback，刷新行为树日志</span></span>
<span class="line"><span>  → 按 bt_loop_duration 休眠</span></span>
<span class="line"><span>  → 再次 tick</span></span></code></pre></div><p>默认 <code>bt_loop_duration</code> 为 10 ms。这里使用 <code>WallRate</code>，如果一次 tick 和回调处理超过周期，系统会发出 tick rate exceeded 告警，而不是同时启动另一个 tick。</p><h2 id="四、一次-tick-怎样变成-ros-2-action" tabindex="-1">四、一次 tick 怎样变成 ROS 2 Action <a class="header-anchor" href="#四、一次-tick-怎样变成-ros-2-action" aria-label="Permalink to &quot;四、一次 tick 怎样变成 ROS 2 Action&quot;">​</a></h2><p>以 <code>ComputePathToPose</code> 为例，它继承 <code>BtActionNode&lt;nav2_msgs::action::ComputePathToPose&gt;</code>。</p><p><img src="`+l+`" alt="图 3：BtActionNode 单次 tick 时序"></p><h3 id="_4-1-首次-tick-并发送-goal" tabindex="-1">4.1 首次 Tick 并发送 Goal <a class="header-anchor" href="#_4-1-首次-tick-并发送-goal" aria-label="Permalink to &quot;4.1 首次 Tick 并发送 Goal&quot;">​</a></h3><p>节点第一次从 <code>IDLE</code> 被 tick 时，会把自己设为 <code>RUNNING</code>，执行派生类的 <code>on_tick()</code>，从 XML 输入端口读取 <code>goal</code>、<code>planner_id</code> 和可选起点，然后调用 <code>async_send_goal()</code>。</p><h3 id="_4-2-推进异步-action" tabindex="-1">4.2 推进异步 Action <a class="header-anchor" href="#_4-2-推进异步-action" aria-label="Permalink to &quot;4.2 推进异步 Action&quot;">​</a></h3><p>这次调用不会阻塞整个行为树直到规划结束。节点使用自己的互斥 callback group 和 <code>SingleThreadedExecutor</code>，每次 tick 只处理一小段异步进展：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>等待 GoalHandle → RUNNING</span></span>
<span class="line"><span>GoalHandle 已确认但结果未到 → spin_some() → RUNNING</span></span>
<span class="line"><span>结果到达 → 映射为 SUCCESS／FAILURE</span></span>
<span class="line"><span>超过 server_timeout → FAILURE</span></span></code></pre></div><p>为了避免一次等待吃掉整个行为树周期，单次内部等待上限被设为 <code>bt_loop_duration × 0.5</code>。因此其他条件节点、控制节点和外层反馈仍能持续推进。</p><h3 id="_4-3-处理规划结果" tabindex="-1">4.3 处理规划结果 <a class="header-anchor" href="#_4-3-处理规划结果" aria-label="Permalink to &quot;4.3 处理规划结果&quot;">​</a></h3><p>规划成功后，<code>ComputePathToPoseAction::on_success()</code> 把返回的 <code>nav_msgs/Path</code> 写入输出端口 <code>path</code>。规划中止或节点被 halt 时，它会写入空路径，避免旧路径继续污染后续执行。</p><h3 id="_4-4-更新-followpath-goal" tabindex="-1">4.4 更新 FollowPath Goal <a class="header-anchor" href="#_4-4-更新-followpath-goal" aria-label="Permalink to &quot;4.4 更新 FollowPath Goal&quot;">​</a></h3><p><code>FollowPathAction</code> 以相同框架调用 <code>/follow_path</code>。它在等待结果期间不断重新读取 Blackboard 中的 <code>path</code>。一旦周期重规划生成了新路径，就设置 <code>goal_updated_</code> 并向 controller server 发送更新后的目标。</p><p>这正是 Nav2 能“边控制边重规划”的关键：规划器更新共享路径，控制节点在后续 tick 中发现变化，再更新底层 FollowPath Goal。</p><h2 id="五、blackboard-不是缓存-而是数据总线" tabindex="-1">五、Blackboard 不是缓存，而是数据总线 <a class="header-anchor" href="#五、blackboard-不是缓存-而是数据总线" aria-label="Permalink to &quot;五、Blackboard 不是缓存，而是数据总线&quot;">​</a></h2><p>XML 中的 <code>{goal}</code>、<code>{path}</code> 不是字符串替换，而是 Blackboard 端口绑定。</p><p><img src="`+p+`" alt="图 4：Blackboard 数据交换"></p><h3 id="_5-1-传递目标与路径" tabindex="-1">5.1 传递目标与路径 <a class="header-anchor" href="#_5-1-传递目标与路径" aria-label="Permalink to &quot;5.1 传递目标与路径&quot;">​</a></h3><p>默认单目标导航中，最重要的数据闭环是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NavigateToPose Goal</span></span>
<span class="line"><span>  → Blackboard[goal]</span></span>
<span class="line"><span>  → ComputePathToPose.goal</span></span>
<span class="line"><span>  → planner_server</span></span>
<span class="line"><span>  → ComputePathToPose.path</span></span>
<span class="line"><span>  → Blackboard[path]</span></span>
<span class="line"><span>  → FollowPath.path</span></span>
<span class="line"><span>  → controller_server</span></span></code></pre></div><h3 id="_5-2-生成外层-action-feedback" tabindex="-1">5.2 生成外层 Action Feedback <a class="header-anchor" href="#_5-2-生成外层-action-feedback" aria-label="Permalink to &quot;5.2 生成外层 Action Feedback&quot;">​</a></h3><p>Blackboard 还连接了行为树与外层 Action feedback。</p><p>每轮 <code>onLoop()</code> 中，<code>NavigateToPoseNavigator</code> 查询当前 TF 位姿，从 Blackboard 读取当前全局路径，计算路径剩余距离；同时从 <code>odom_smoother</code> 获取速度，估算剩余时间，再读取 <code>number_recoveries</code>。</p><p>最终发布的外层反馈包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>current_pose</span></span>
<span class="line"><span>navigation_time</span></span>
<span class="line"><span>estimated_time_remaining</span></span>
<span class="line"><span>number_of_recoveries</span></span>
<span class="line"><span>distance_remaining</span></span></code></pre></div><p>需要区分两层反馈：树内 <code>/follow_path</code> feedback 由 <code>BtActionNode</code> 接收，用来驱动具体插件逻辑；外层 <code>/navigate_to_pose</code> feedback 则由 Navigator 每轮汇总 TF、路径、速度和恢复计数后发布。</p><h2 id="六、service-节点怎样接入" tabindex="-1">六、Service 节点怎样接入 <a class="header-anchor" href="#六、service-节点怎样接入" aria-label="Permalink to &quot;六、Service 节点怎样接入&quot;">​</a></h2><p><code>BtServiceNode&lt;ServiceT&gt;</code> 与 Action 节点结构相似，但它处理的是一次请求和一次响应。</p><h3 id="_6-1-构造并发送-service-request" tabindex="-1">6.1 构造并发送 Service Request <a class="header-anchor" href="#_6-1-构造并发送-service-request" aria-label="Permalink to &quot;6.1 构造并发送 Service Request&quot;">​</a></h3><p>第一次 tick 时，派生类在 <code>on_tick()</code> 填充 request，然后执行 <code>async_send_request()</code>。</p><h3 id="_6-2-检查异步响应" tabindex="-1">6.2 检查异步响应 <a class="header-anchor" href="#_6-2-检查异步响应" aria-label="Permalink to &quot;6.2 检查异步响应&quot;">​</a></h3><p>后续 tick 使用独立 executor 检查 future：响应完成则调用 <code>on_completion()</code>，未完成且未超时则返回 <code>RUNNING</code>，超时则返回 <code>FAILURE</code>。</p><h3 id="_6-3-调用-clear-costmap-service" tabindex="-1">6.3 调用 Clear Costmap Service <a class="header-anchor" href="#_6-3-调用-clear-costmap-service" aria-label="Permalink to &quot;6.3 调用 Clear Costmap Service&quot;">​</a></h3><p>例如 <code>ClearEntireCostmap</code> 调用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global_costmap/clear_entirely_global_costmap</span></span>
<span class="line"><span>local_costmap/clear_entirely_local_costmap</span></span></code></pre></div><p>清图动作开始时还会递增 Blackboard 中的 <code>number_recoveries</code>，所以 RViz2 看到的恢复次数并不是 <code>RecoveryNode</code> 重试轮数，而是具体恢复插件主动累计的次数。</p><h2 id="七、默认导航树如何安排规划与控制" tabindex="-1">七、默认导航树如何安排规划与控制 <a class="header-anchor" href="#七、默认导航树如何安排规划与控制" aria-label="Permalink to &quot;七、默认导航树如何安排规划与控制&quot;">​</a></h2><p>默认 <code>navigate_to_pose_w_replanning_and_recovery.xml</code> 的主流程由三层关键控制节点组成。</p><p><img src="`+r+`" alt="图 5：默认导航树和分层恢复"></p><h3 id="_7-1-pipelinesequence-让上游持续更新" tabindex="-1">7.1 PipelineSequence：让上游持续更新 <a class="header-anchor" href="#_7-1-pipelinesequence-让上游持续更新" aria-label="Permalink to &quot;7.1 PipelineSequence：让上游持续更新&quot;">​</a></h3><p>普通 Sequence 中，前一个孩子成功后通常不会在后续周期重新执行。<code>PipelineSequence</code> 则会在后面的孩子仍为 <code>RUNNING</code> 时重新 tick 已经走过的上游节点。</p><p>配合 <code>RateController hz=&quot;1.0&quot;</code>，它形成如下流水线：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每秒重新计算一次全局路径</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>FollowPath 持续控制机器人</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>路径变化后更新 controller server 的目标</span></span></code></pre></div><h3 id="_7-2-局部-recoverynode-先处理上下文故障" tabindex="-1">7.2 局部 RecoveryNode：先处理上下文故障 <a class="header-anchor" href="#_7-2-局部-recoverynode-先处理上下文故障" aria-label="Permalink to &quot;7.2 局部 RecoveryNode：先处理上下文故障&quot;">​</a></h3><p>规划分支失败时，先清理 global costmap，再重试一次规划。</p><p>控制分支失败时，先清理 local costmap，再重试一次控制。</p><p><code>RecoveryNode</code> 必须恰好有两个孩子。第一个孩子是主任务，第二个孩子是恢复动作。主任务失败且仍有重试额度时，它 halt 主任务、执行恢复；恢复成功后增加重试计数，再回到第一个孩子。</p><h3 id="_7-3-系统级-recoverynode-轮换恢复策略" tabindex="-1">7.3 系统级 RecoveryNode：轮换恢复策略 <a class="header-anchor" href="#_7-3-系统级-recoverynode-轮换恢复策略" aria-label="Permalink to &quot;7.3 系统级 RecoveryNode：轮换恢复策略&quot;">​</a></h3><p>如果局部恢复仍不能解决问题，最外层 <code>NavigateRecovery</code> 执行系统级恢复分支。</p><p><code>ReactiveFallback</code> 先检查 <code>GoalUpdated</code>。目标已经改变时，当前恢复链可以被新目标打断；否则进入 <code>RoundRobin</code>，依次尝试：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>清理 local 和 global costmap</span></span>
<span class="line"><span>→ 原地旋转</span></span>
<span class="line"><span>→ 等待</span></span>
<span class="line"><span>→ 后退</span></span></code></pre></div><p><code>RoundRobin</code> 每次有一个孩子成功，就记住下一次应从哪个孩子开始；只有所有孩子都失败才整体失败。恢复成功后，外层 <code>RecoveryNode</code> 回到主导航流程重新规划和控制，最多进行 XML 指定的 6 轮系统级重试。</p><h2 id="八、条件节点和装饰节点控制-什么时候执行" tabindex="-1">八、条件节点和装饰节点控制“什么时候执行” <a class="header-anchor" href="#八、条件节点和装饰节点控制-什么时候执行" aria-label="Permalink to &quot;八、条件节点和装饰节点控制“什么时候执行”&quot;">​</a></h2><p>Action 和 Service 决定“做什么”，Condition、Decorator 和 Control 节点决定“何时做、按什么顺序做”。</p><p>典型 Condition 包括 <code>GoalUpdated</code>、<code>GoalReached</code>、<code>IsPathValid</code>、<code>IsStuck</code>、<code>TransformAvailable</code> 和电池状态判断。它们读取 Blackboard、TF、Topic 或 Service，只返回 <code>SUCCESS</code> 或 <code>FAILURE</code>，用结果改变树的分支。</p><p>典型 Decorator 包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RateController       限制孩子 tick 频率</span></span>
<span class="line"><span>DistanceController   每移动一定距离触发</span></span>
<span class="line"><span>SpeedController      根据速度调整执行频率</span></span>
<span class="line"><span>SingleTrigger        只触发一次</span></span>
<span class="line"><span>GoalUpdatedController 目标更新时放行</span></span></code></pre></div><p>这使同一批规划、控制和恢复插件可以通过不同 XML 组合出不同导航策略，而不需要重新编译 Navigator。</p><h2 id="九、取消和-halt-为什么必须向下传播" tabindex="-1">九、取消和 halt 为什么必须向下传播 <a class="header-anchor" href="#九、取消和-halt-为什么必须向下传播" aria-label="Permalink to &quot;九、取消和 halt 为什么必须向下传播&quot;">​</a></h2><p>如果用户取消 <code>/navigate_to_pose</code>，只停止外层循环是不够的。此时 <code>/compute_path_to_pose</code>、<code>/follow_path</code> 或 <code>/spin</code> 可能仍在底层服务器执行。</p><p><img src="`+d+`" alt="图 6：取消、抢占和结果闭环"></p><h3 id="_9-1-检查取消并-halt-根节点" tabindex="-1">9.1 检查取消并 Halt 根节点 <a class="header-anchor" href="#_9-1-检查取消并-halt-根节点" aria-label="Permalink to &quot;9.1 检查取消并 Halt 根节点&quot;">​</a></h3><p><code>BehaviorTreeEngine::run()</code> 每轮 tick 前检查取消请求。发现取消后，它先调用根节点 <code>halt()</code>，再返回 <code>BtStatus::CANCELED</code>。</p><h3 id="_9-2-向底层-action-传播-halt" tabindex="-1">9.2 向底层 Action 传播 Halt <a class="header-anchor" href="#_9-2-向底层-action-传播-halt" aria-label="Permalink to &quot;9.2 向底层 Action 传播 Halt&quot;">​</a></h3><p>控制节点会把 halt 传播给正在运行的孩子。<code>BtActionNode::halt()</code> 检查底层 GoalHandle；如果 Action 仍为 <code>ACCEPTED</code> 或 <code>EXECUTING</code>，就发送异步取消，并等待 cancel 与 result future 完成，最后把自身重置为 <code>IDLE</code>。</p><h3 id="_9-3-清理残留-running-节点" tabindex="-1">9.3 清理残留 Running 节点 <a class="header-anchor" href="#_9-3-清理残留-running-节点" aria-label="Permalink to &quot;9.3 清理残留 Running 节点&quot;">​</a></h3><p>执行回调结束后，<code>haltAllActions()</code> 还会递归访问整棵树，对任何仍为 <code>RUNNING</code> 的节点再次调用 halt。这是最后一道一致性保护。</p><h3 id="_9-4-映射最终状态" tabindex="-1">9.4 映射最终状态 <a class="header-anchor" href="#_9-4-映射最终状态" aria-label="Permalink to &quot;9.4 映射最终状态&quot;">​</a></h3><p>最终映射关系为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BT SUCCESS  → succeeded_current(result)</span></span>
<span class="line"><span>BT FAILURE  → terminate_current(result)</span></span>
<span class="line"><span>BT CANCELED → terminate_all(result)</span></span></code></pre></div><h2 id="十、抢占不是无条件换树" tabindex="-1">十、抢占不是无条件换树 <a class="header-anchor" href="#十、抢占不是无条件换树" aria-label="Permalink to &quot;十、抢占不是无条件换树&quot;">​</a></h2><p>导航运行期间收到 pending goal 时，<code>onLoop()</code> 会调用 Navigator 的 <code>onPreempt()</code>。</p><p>只有新旧目标使用同一份行为树 XML，才接受真正的抢占，并直接更新 Blackboard 中的目标。这样当前树能够继续运行，规划节点在下一轮读取到新目标。</p><p>如果 pending goal 指定了不同 XML，系统会拒绝该 pending goal，并继续执行当前导航。原因很直接：运行中替换整棵树需要先取消旧树，而不是在同一执行上下文里无缝抢占。</p><h2 id="十一、行为树状态如何被观测" tabindex="-1">十一、行为树状态如何被观测 <a class="header-anchor" href="#十一、行为树状态如何被观测" aria-label="Permalink to &quot;十一、行为树状态如何被观测&quot;">​</a></h2><p>每次树节点状态变化时，<code>RosTopicLogger</code> 记录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>节点名称</span></span>
<span class="line"><span>前一状态</span></span>
<span class="line"><span>当前状态</span></span>
<span class="line"><span>状态变化时间</span></span></code></pre></div><p>每轮 <code>onLoop()</code> 调用 <code>flush()</code>，把累计事件发布到 <code>/behavior_tree_log</code>。因此这个 Topic 描述的是树节点状态迁移，不是导航 Action feedback，也不是 Groot 的 XML 模型文件。</p><p>排障时可以按数据层级检查：</p><h3 id="_11-1-检查外层目标" tabindex="-1">11.1 检查外层目标 <a class="header-anchor" href="#_11-1-检查外层目标" aria-label="Permalink to &quot;11.1 检查外层目标&quot;">​</a></h3><p>确认外层目标是否进入 <code>/navigate_to_pose/_action/status</code>。</p><h3 id="_11-2-检查行为树状态日志" tabindex="-1">11.2 检查行为树状态日志 <a class="header-anchor" href="#_11-2-检查行为树状态日志" aria-label="Permalink to &quot;11.2 检查行为树状态日志&quot;">​</a></h3><p>确认 <code>/behavior_tree_log</code> 中哪个节点从 <code>RUNNING</code> 变为 <code>FAILURE</code>。</p><h3 id="_11-3-检查底层接口" tabindex="-1">11.3 检查底层接口 <a class="header-anchor" href="#_11-3-检查底层接口" aria-label="Permalink to &quot;11.3 检查底层接口&quot;">​</a></h3><p>确认对应底层 Action 或 Service 是否在线，例如 <code>/compute_path_to_pose</code>、<code>/follow_path</code> 和 costmap clear 服务。</p><h3 id="_11-4-检查-blackboard-数据" tabindex="-1">11.4 检查 Blackboard 数据 <a class="header-anchor" href="#_11-4-检查-blackboard-数据" aria-label="Permalink to &quot;11.4 检查 Blackboard 数据&quot;">​</a></h3><p>确认 Blackboard 关键数据是否有效，尤其是 <code>goal</code>、<code>path</code> 和恢复次数。</p><h3 id="_11-5-检查取消状态" tabindex="-1">11.5 检查取消状态 <a class="header-anchor" href="#_11-5-检查取消状态" aria-label="Permalink to &quot;11.5 检查取消状态&quot;">​</a></h3><p>确认取消后底层 Action 是否同步进入 canceled 状态。</p><h2 id="十二、最容易混淆的五个边界" tabindex="-1">十二、最容易混淆的五个边界 <a class="header-anchor" href="#十二、最容易混淆的五个边界" aria-label="Permalink to &quot;十二、最容易混淆的五个边界&quot;">​</a></h2><h3 id="_12-1-tick-不是全局-spin" tabindex="-1">12.1 Tick 不是全局 Spin <a class="header-anchor" href="#_12-1-tick-不是全局-spin" aria-label="Permalink to &quot;12.1 Tick 不是全局 Spin&quot;">​</a></h3><p>行为树 tick 不是 ROS executor 的全局 spin。每个 BT Action／Service 节点拥有自己的 callback group executor，并在 tick 内有限度推进异步回调。</p><h3 id="_12-2-running-不代表持续占用线程" tabindex="-1">12.2 <code>RUNNING</code> 不代表持续占用线程 <a class="header-anchor" href="#_12-2-running-不代表持续占用线程" aria-label="Permalink to &quot;12.2 \`RUNNING\` 不代表持续占用线程&quot;">​</a></h3><p><code>RUNNING</code> 不是线程一直占用 CPU。它表示异步任务尚未完成，控制权已经返回行为树主循环。</p><h3 id="_12-3-blackboard-path-是实时通道" tabindex="-1">12.3 Blackboard Path 是实时通道 <a class="header-anchor" href="#_12-3-blackboard-path-是实时通道" aria-label="Permalink to &quot;12.3 Blackboard Path 是实时通道&quot;">​</a></h3><p>Blackboard 中的 <code>path</code> 不只是规划结果存档，它还是规划器向控制器更新目标的实时通道。</p><h3 id="_12-4-恢复次数不等于所有重试次数" tabindex="-1">12.4 恢复次数不等于所有重试次数 <a class="header-anchor" href="#_12-4-恢复次数不等于所有重试次数" aria-label="Permalink to &quot;12.4 恢复次数不等于所有重试次数&quot;">​</a></h3><p>恢复次数不是所有重试的总和。当前实现由具体恢复 Action／Service 插件调用 <code>increment_recovery_count()</code> 维护。</p><h3 id="_12-5-xml、插件库与-ros-graph-缺一不可" tabindex="-1">12.5 XML、插件库与 ROS Graph 缺一不可 <a class="header-anchor" href="#_12-5-xml、插件库与-ros-graph-缺一不可" aria-label="Permalink to &quot;12.5 XML、插件库与 ROS Graph 缺一不可&quot;">​</a></h3><p>XML 决定调用结构，插件库决定 XML 标签能否执行，ROS graph 决定底层调用能否真正完成。三者缺一不可。</p><h2 id="十三、结语" tabindex="-1">十三、结语 <a class="header-anchor" href="#十三、结语" aria-label="Permalink to &quot;十三、结语&quot;">​</a></h2><p><code>nav2_behavior_tree</code> 的价值不在于替代规划和控制算法，而在于把分散的 ROS 2 能力组织成一套可观察、可取消、可恢复、可替换策略的导航运行时。</p><p>从数据角度看，它完成了三次关键转换：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>导航目标 → Blackboard 数据</span></span>
<span class="line"><span>Blackboard 数据 → 底层 Action／Service 请求</span></span>
<span class="line"><span>底层结果 → 树状态、恢复分支和外层导航结果</span></span></code></pre></div><p>理解这三次转换后，再看复杂的 Nav2 XML，就不再是一堆嵌套标签，而是一张清晰的数据流与状态调度图。</p>`,158)])])}const x=e(h,[["render",b]]);export{q as __pageData,x as default};
